import { promises as fs } from "fs";
import path from "path";
import type { TranslationId } from "@/lib/translation-ids";

export { TRANSLATIONS, translationsFromParam } from "@/lib/translation-ids";
export type { TranslationId } from "@/lib/translation-ids";

/**
 * Translations and tafsir, generated by `node scripts/build-content.mjs` into
 * public/data/translations/<id>.json. Each file has a credit and 6236 texts in verse order.
 * Server-only (build time): it reads the files from disk.
 */
export interface Translation {
  credit: string;
  text: string[];
}

export async function loadTranslation(id: TranslationId): Promise<Translation | null> {
  try {
    const file = path.join(process.cwd(), "public", "data", "translations", `${id}.json`);
    const data = JSON.parse(await fs.readFile(file, "utf8")) as Translation;
    return data.text?.length === 6236 ? data : null;
  } catch {
    return null;
  }
}
